L41_1.m_Pos = "R"
L41_1.m_Talk_KOREA = "대령, 종이와 펜을 준비하게. 그리고 지금부터 내가 말하는 걸 받아 적어."
L41_1.m_fTalkTime = 0.03
L41_1.m_Talk_JPN = "大佐、紙とペンを用意するように。それから、今から私が話すことをそのまま書いてくれ。"
L41_1.m_Talk_ENG = "Colonel, take out a pen and paper and write down what I'm about to say."
