L43_1.m_Pos = "R"
L44_1 = "그래. 마지막 제물만이 남은 지금. 광기는 자욱한 안개의 형태로 런던을 침식하고 있어."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "そうだ。最後の生贄だけが残っている今、狂気は立ち込める霧のごとくロンドンを侵食している。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Yes. With the last sacrifice left, madness is encroaching London in the form of a thick fog."
L43_1.m_Talk_ENG = L44_1
L44_1 = "是的。現在只差最後的祭品。瘋狂就會像這場濃霧一樣侵蝕整個倫敦。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "是的。现在只差最后的祭品。疯狂就会像这场浓雾一样侵蚀整个伦敦。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Yes. With the last sacrifice left, madness is encroaching London in the form of a thick fog."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Yes. With the last sacrifice left, madness is encroaching London in the form of a thick fog."
L43_1.m_Talk_FRA = L44_1
