L44_1.m_Pos = "R"
L45_1 = "이 기묘하고 납득할 수 없는 사건은 심야의 살인마라는 심볼 아래에 이름을 갖게 되고."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "この奇妙かつ納得しがたい事件は、深夜の殺人鬼というシンボルをもとに名を得て、"
L44_1.m_Talk_JPN = L45_1
