L46_1 = "무지몽매한 대중들의 무의식으로부터 비롯된 힘을 하나로 결집시키게 될 거라네."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "何も知らない大衆が無意識に生んだ力を一つにまとめることになる。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "The power that comes from the unconsciousness of the ignorant public will be united as one."
L45_1.m_Talk_ENG = L46_1
L46_1 = "將無知大眾的無意識之力彙聚成一體。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "将无知大众的无意识之力汇聚成一体。"
