L46_1 = "The power that comes from the unconsciousness of the ignorant public will be united as one."
L45_1.m_Talk_DEU = L46_1
L46_1 = "The power that comes from the unconsciousness of the ignorant public will be united as one."
L45_1.m_Talk_FRA = L46_1
