L48_1 = "외부 세계로부터 신적 존재를 끌어내, 끝내 금빛 새벽을 맞이하게 하는 것도 가능해."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "外部世界から神的存在を呼び出し、やがては金色の暁を迎えることも可能だ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Also, summoning the divine being from the outside world, and finally bringing about the golden dawn would become possible."
