L16_1 = "이번에는 자기가 심야의 살인마라는 증거로 훼손한 시체의 일부를 보냈다나 봐."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "今回は自分が深夜の殺人鬼だという証拠として、死体の一部を送ったそうだよ。"
L15_1.m_Talk_JPN = L16_1
