L21_1 = "L"
L20_1.m_Pos = L21_1
L21_1 = "참 나, 그깟 더러운 마녀들이 뭐라고. 이렇게 소란이야?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "まったく、ただの汚い魔女くらいで、こんなに騒ぐことか？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Ugh, why cause all this fuss over some dirty witches no one cares about?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "真是的，那些骯髒的魔女死了就死了。怎麼搞得這麼吵？"
L20_1.m_Talk_TWN = L21_1
L21_1 = "真是的，那些肮脏的魔女死了就死了。怎么搞得这么吵？"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ugh, why cause all this fuss over some dirty witches no one cares about?"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Ugh, why cause all this fuss over some dirty witches no one cares about?"
L20_1.m_Talk_FRA = L21_1
