L22_1 = "SWANSONG_ACT3_INTERLUDE1@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 6800301
L21_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE1"
