L21_1.m_CharStrID = L22_1
L22_1 = "L"
L21_1.m_Pos = L22_1
L22_1 = "잘 뒈졌지. 어차피 길바닥에서 퍼지면 마물이나 되어서 사람들을 해칠 텐데 말이야."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "死んでよかったよ。どうせ路地裏で倒れていたら、魔物になって人々を襲ったに違いない。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Good riddance they're dead. If they were left out on the streets, they would've turned into monsters and harmed people."
L21_1.m_Talk_ENG = L22_1
L22_1 = "死得好哇。反正倒在路邊，遲早會變成怪物傷人的。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "死得好哇。反正倒在路边，迟早会变成怪物伤人的。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Good riddance they're dead. If they were left out on the streets, they would've turned into monsters and harmed people."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Good riddance they're dead. If they were left out on the streets, they would've turned into monsters and harmed people."
L21_1.m_Talk_FRA = L22_1
