L23_1 = "잠깐, 어쩌면 왕실에서 이능력자의 수를 줄이려고 심야의 살인마를 고용한 거 아닐까?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "待って、もしかしたら王室が異能力者の数を減らすために深夜の殺人鬼を雇ったんじゃない？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Wait, what if the royal family hired the Midnight Killer to reduce the number of Supernaturals?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "等一下，難道是王室雇了午夜殺人魔來減少超能力者數量嗎？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "等、等一下，难道是王室雇佣了午夜杀人魔来减少异能者数量吗？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wait, what if the royal family hired the Midnight Killer to reduce the number of Supernaturals?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Wait, what if the royal family hired the Midnight Killer to reduce the number of Supernaturals?"
