L32_1.m_Pos = "R"
L32_1.m_Crash = 20
L33_1 = "우리가, 우리 애들이 뭘 잘못했다고!! 우리도 피해자야!!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "私たち、そしてうちの子どもたちがいったい何をしたっていうの！！　私たちも被害者なのよ！！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "What... what did our children do wrong?! We're victims too!!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "那些，那些孩子做錯了什麼！！我們也是受害者！！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "那些、那些孩子做错了什么！！我们也是受害者！！"
