L35_1 = "그럼, 너희가 사람인 것 같아? 그 잘난 이능력도 서서히 마물로 변해간다는 증거겠지!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "お前らのどこが人間だって言うんだ！　そのご大層な異能力だって徐々に魔物と化してるって証拠なんだろ？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Then, do you think you are human? The proof is how their special powers slowly turn them into monsters!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "看看你們，還覺得自己是人類嗎？那些所謂的異能也不過是逐漸變成怪物的證據而已！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "看看你们，还觉得自己是人类吗？那些所谓的异能也不过是逐渐变成魔物的证据罢了！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Then, do you think you are human? The proof is how their special powers slowly turn them into monsters!"
