L28_1.m_CharStrID = L29_1
L29_1 = "어디 쏴 볼 테면 쏴 봐! 어차피 여왕에게 죽나, 심야의 살인마에게 도륙당하나 똑같아!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ほら、撃てよ！　どうせ女王に殺されようが、深夜の殺人鬼に殺されようが一緒だ！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Try and shoot me! Being killed by the Queen or slaughtered by the Midnight Killer, it's all the same to me!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "有本事就開槍吧！反正死在女王手裡，還是被殺人魔殺掉，結果都一樣！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "有本事就开枪吧！反正死在女王手里，还是被杀人魔杀掉，结果都一样！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Try and shoot me! Being killed by the Queen or slaughtered by the Midnight Killer, it's all the same to me!"
L28_1.m_Talk_DEU = L29_1
