L44_1 = "그동안 수많은 사건을 해결해 오면서 한가지 깨달은 게 있어."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "今まで様々な事件を解決してきて、気づいたことがあるんだ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "After solving countless cases, there is one thing that I came to realize."
L43_1.m_Talk_ENG = L44_1
L44_1 = "在解決了無數案件的過程中，我明白了一件事。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "在解决了无数案件的过程中，我明白了一件事。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "After solving countless cases, there is one thing that I came to realize."
L43_1.m_Talk_DEU = L44_1
L44_1 = "After solving countless cases, there is one thing that I came to realize."
L43_1.m_Talk_FRA = L44_1
