L45_1 = "SWANSONG_ACT3_INTERLUDE1@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 6800301
L44_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE1"
