L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L44_1.m_Pos = "C"
L45_1 = "우리의 운명이라는 보이지 않는 실타래 속에는 사실, 선홍색의 실이 얽혀 있다는 걸."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "私たちの運命という目に見えない糸には、深紅に染まった糸が絡まっている。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "It's that within the invisible threads of destiny, our fates are actually intertwined by a bright red thread."
L44_1.m_Talk_ENG = L45_1
L45_1 = "在我們那個名為命運的無形線團裡，其實還纏繞著一根鮮紅色的細線。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "在我们那个名为命运的无形线团里，其实还缠绕着一根鲜红色的细线。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "It's that within the invisible threads of destiny, our fates are actually intertwined by a bright red thread."
L44_1.m_Talk_DEU = L45_1
L45_1 = "It's that within the invisible threads of destiny, our fates are actually intertwined by a bright red thread."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "SWANSONG_ACT3_INTERLUDE1@195#Talk"
