L45_1.m_Pos = "C"
L46_1 = "언뜻 보면, 전혀 상관없는 것들이……. 복잡하게 얽히고 얽혀 어떤 사건을 만들어 내지."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "最初は何の関係もなく思えても……いつしか複雑に絡み合い、ある出来事を作り出す。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "The things that seem unrelated at first glance... get tangled together to create an event."
L45_1.m_Talk_ENG = L46_1
L46_1 = "乍一看，是完全無關的事物……複雜地交織在一起，才製造出了某種事件。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "乍一看，是完全无关的事物……复杂地交织在一起，才制造出了某种事件。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "The things that seem unrelated at first glance... get tangled together to create an event."
L45_1.m_Talk_DEU = L46_1
L46_1 = "The things that seem unrelated at first glance... get tangled together to create an event."
L45_1.m_Talk_FRA = L46_1
