L48_1.m_Pos = "C"
L49_1 = "자네가 말했지? 매일 같이 런던 빈민들이 실종되더라도 세상은 멀쩡히 돌아갈 거라고?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "君が言っただろう？　毎日ロンドンの貧民が失踪しても、世界は何も問題なく、日常は続くと。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "You said it yourself. That the world will continue to be fine even if London's poor go missing."
L48_1.m_Talk_ENG = L49_1
L49_1 = "你說，即使每天都有倫敦的貧民失蹤，世界也會照常運轉？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "你说，即使每天都有伦敦的贫民失踪，世界也会照常运转？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "You said it yourself. That the world will continue to be fine even if London's poor go missing."
L48_1.m_Talk_DEU = L49_1
L49_1 = "You said it yourself. That the world will continue to be fine even if London's poor go missing."
