L50_1 = "심야의 살인마가 누굴 죽이든, 자네와는 전혀 상관없는 일이라고?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "深夜の殺人鬼が誰を殺そうとも、君とはまったく関係のないことだと。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Do you really think the Midnight Killer's murders have nothing to do with you?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "那麼午夜殺人魔殺了人，就完全和你沒有一點關係了嗎？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "那么午夜杀人魔杀了人，就完全和你没有一点关系了吗？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Do you really think the Midnight Killer's murders have nothing to do with you?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Do you really think the Midnight Killer's murders have nothing to do with you?"
