L32_1 = "네가 그랬지? 런던 시민들에게 사랑받는 프리마돈나라서 부럽다고?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "あなた、言ったよね？　ロンドンの市民から愛されるプリマドンナで羨ましいって。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Didn't you say that you were jealous of me being London's beloved prima donna?"
