L32_1.m_CharScaleTime = 0.01
L33_1 = "무대 앞에 서고 싶다고, 나처럼 예쁘고 재능 있었으면 좋겠다고 했잖아?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "舞台に立ちたい、私みたいに綺麗で才能があったらいいなって言ったよね？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "That you wanted to stand on the stage? Or that you wanted to be pretty and talented as me?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "你說過想站在舞台前，想像我一樣美麗又有才華，對吧？"
