L34_1 = "이게 그 실체야. 너희들이 더럽다며 멸시하는 이능력자."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "これが私の正体よ。あなたたちが汚いって軽蔑している異能力者。"
