L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "R"
L40_1 = "원하든, 원치 않든 한 번 본 대본이나 노래, 연기는 머릿속에서 지워지지 않으니까."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "たとえ望んでいなくても、一度見た台本や歌、演技は頭から消えないから。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Whether I liked it or not, I can't get the script, song, or acting out of my head."
L39_1.m_Talk_ENG = L40_1
L40_1 = "無論我是否願意，一旦看過的劇本、歌曲或者表演，就不會再從腦海中消失。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "无论我是否愿意，一旦看过的剧本、歌曲或者表演，就不会再从脑海中消失。"
L39_1.m_Talk_SCN = L40_1
