L16_1.m_Talk_JPN = L17_1
L17_1 = "I've been watching you up close for all this time, so I know."
L16_1.m_Talk_ENG = L17_1
L17_1 = "因為一直以來我都是距離你最近的人，所以我知道。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "因为一直以来我都是距离你最近的人，所以我知道。"
