L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "人々が注目しない舞台裏で、あなたが一人でどれだけたくさん悩み、苦しんでいたのかを。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I know how you struggle alone behind the stage where no one pays attention."
