L17_1.m_Talk_TWN = L18_1
L18_1 = "在人们不注意的舞台背后，你一个人究竟有多么辛苦、多么苦恼。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "I know how you struggle alone behind the stage where no one pays attention."
