L34_1 = "동생이 있었거든. 피는 이어지지 않았지만 살아있다면 네 또래 정도 됐을 거야."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "妹がいたんだ。血は繋がってないけど、生きてたらあなたと同い年くらいだと思う。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I had a sister. Although we weren't related by blood, if she was alive, she'd be about your age."
L33_1.m_Talk_ENG = L34_1
L34_1 = "我有個妹妹。雖然沒有血緣關係，但如果她還活著的話，應該和你差不多大。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "我有个妹妹。虽然没有血缘关系，但如果她还活着的话，应该和你差不多大。"
