L9_1.m_Pos = "R"
L10_1 = "나는 널 한 번도 동등한 관계라고 생각한 적 없어! 그러니까 네가 날 도와줄 이유도 없다고!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "私は一度もあなたと同等な関係だと思ったことない！　だからあなたが私を助ける理由なんてないの！"
